INSERT INTO `email_template` VALUES (13, 'WR returned by technician', 'For assigned technician', 'GEMS 2.0 - Work Request Returned', '<p>Dear [fullName],</p>\r\n<p>A work request task with task no = [task_no] was returned by technician.</p>\r\n<p>Comment : [comment]</p>\r\n<p>Please open the mobile apps and assigned back the task to right technician.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (14, 'WR invalid', 'For complainer invalid', 'GEMS 2.0 - Work Request Invalid', '<p>Dear [fullName],</p>\r\n<p>A work request no = [task_no] was rejected and invalid.</p>\r\n<p>Comment : [comment]</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (15, 'WR returned by verifier', 'For technician', 'GEMS 2.0 - Work Request Re-Open', '<p>Dear [fullName],</p>\r\n<p>A work request task with task no = [task_no] was Re-Open by WR Verifier.</p>\r\n<p>Comment : [comment]</p>\r\n<p>Please open the mobile apps and perform back the work.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (16, 'WO verify part request', 'For supervisor', 'GEMS 2.0 - Work Order Part Request Verification', '<p>Dear [fullName],</p>\r\n<p>You have received 1 new part request task (Request No = [request_no]) for Work Order No [wo_no] to be verify and approved.</p>\r\n<p>Please open the mobile apps to verify the work order part request.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (17, 'WO process part request', 'For storekeeper', 'GEMS 2.0 - Work Order Part Request', '<p>Dear [fullName],</p>\r\n<p>You have received 1 new part request task (Request No = [request_no]) for Work Order No [wo_no] to be processed.</p>\r\n<p>Please open the mobile apps to check the work order part request.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (18, 'WO reserve part request', 'For technician', 'GEMS 2.0 - Work Order Part Request Ready for Collection', '<p>Dear [fullName],</p>\r\n<p>Your requested parts (Request No = [request_no]) for Work Order No [wo_no] is now ready for collection.</p>\r\n<p>Please collect your requested part from the storekeeper and show the Request No. for verification.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (19, 'WO collect part request', 'For technician', 'GEMS 2.0 - Work Order Part Request Collected', '<p>Dear [fullName],</p>\r\n<p>Your requested parts (Request No = [request_no]) for Work Order No [wo_no] is successfully collected.</p>\r\n<p>Please open the mobile apps to resume the work order task.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (20, 'WO reject part request', 'For technician', 'GEMS 2.0 - Work Order Part Request Rejected', '<p>Dear [fullName],</p>\r\n<p>Your requested parts (Request No = [request_no]) for Work Order No [wo_no] is been rejected.</p>\r\n<p>Comment : [comment]</p>\r\n<p>Please open the mobile apps to reapply or resume the work order task.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (21, 'FCA audit recommendation', 'For Auditor', 'GEMS 2.0 - FCA Audit  Recommendation', '<p>Dear [fullName],</p>\r\n<p>You have received 1 new FCA audit task (audit no = [task_no]) to be recommended.</p>\r\n<p>Observation : [observation]</p>\r\n<p>Please login to https://gems.globalfm.com.my and check the FCA task.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (22, 'FCA audit validation', 'For Auditor', 'GEMS 2.0 - FCA Audit Validation', '<p>Dear [fullName],</p>\r\n<p>There is 1 new FCA audit task (audit no = [task_no]) available to be validated.</p>\r\n<p>Recommendation : [recommendation]</p>\r\n<p>Please login to https://gems.globalfm.com.my and check the FCA task.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (23, 'FCA audit correction', 'For Auditor', 'GEMS 2.0 - FCA Audit  Correction', '<p>Dear [fullName],</p>\r\n<p>After validation process, your submitted FCA audit task (audit no = [task_no]) need to be corrected.</p>\r\n<p>Validation Remark : [validation]</p>\r\n<p>Please login to https://gems.globalfm.com.my and correct the FCA form.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (24, 'FCA audit complete', 'For Auditor', 'GEMS 2.0 - FCA Audit  Completed', '<p>Dear [fullName],</p>\r\n<p>The FCA audit task (audit no = [task_no]) is completely validated and done.</p>\r\n<p>Validation Remark : [validation]</p>\r\n<p>Please login to https://gems.globalfm.com.my to review the FCA.</p>\r\n<br /><br />\r\n<p><i>Note: This is an automail from GEMS 2.0 System. Please do not reply to this email.</i></p>', 1);
INSERT INTO `email_template` VALUES (25, 'Space Management Reservation', 'For Reserved User', 'Space Reservation Created', '<p>Hi [fullName],</p><p>Your reservation is confirmed.</p><ul><li>Space: [space_name] ([location_name])</li><li>Start: [reservation_start]</li><li>End: [reservation_end]</li></ul><p>You can reschedule or cancel from My Reservations.</p>', 1);
INSERT INTO `email_template` VALUES (26, 'For Reservation Reschedule', 'For Reserved User', 'Space Reservation Updated', '<p>Hi [fullName],</p><p>Your reservation was updated.</p><ul><li>Space: [space_name] ([location_name])</li><li>Old Start: [old_start] → New Start: [reservation_start]</li><li>Old End: [old_end] → New End: [reservation_end]</li></ul>', 1);
INSERT INTO `email_template` VALUES (27, 'For Cancelled Reservation', 'For Reserved User', 'Space Reservation Canceled', '<p>Hi [fullName],</p><p>Your reservation has been canceled.</p><ul><li>Space: [space_name] ([location_name])</li><li>Start: [reservation_start]</li><li>End: [reservation_end]</li></ul><p>Reason: [cancel_reason]</p>', 1);
