INSERT INTO `kpi_info` VALUES (1, 7, 1, 2, 'Availability of All Management Services and Systems', 'Availability of weekly, monthly, half-yearly and yearly reports', '100% compliance to agreed submission date', 'Submission Records', 0.050, 'Number of Late Reports - Total Reports', 'Need to review submitted reports compliances', 1);
INSERT INTO `kpi_info` VALUES (2, 7, 1, 3, 'General Complaint on Service', 'User General Complaint', 'Maximum of 25 % of total population (permanent user) per month (Allowed Total Complaint, ATC)', 'CMMS Complaint Work Order & requestor verification', 0.100, 'Excess number of complaints ÷ ATC', 'So far all complaints are CLOSED, the needs to have CMMS is CRITICAL (Monthly deduction is applicable)', 1);
INSERT INTO `kpi_info` VALUES (3, 7, 1, 4, 'Resolving General Service Complaint\r', 'Turnaround Time', '75 % of Work Orders (WO) closed within one month\r', 'CMMS Complaint Work Order & requestor verification', 0.100, '(Target number of WO to close in the epriod – Actual WO closed in time) ÷ (Number of WO in the period)', 'All complaints are CLOSED within the same month, but CMMS application is CRITICAL – deduction is applicable', 1);
INSERT INTO `kpi_info` VALUES (4, 7, 1, 5, 'Recurring Complaint on Attended Work Order', 'Recurring Complaint', 'Below 25% monthly work order', 'CMMS Complaint Work Order & requestor verification', 0.050, '(Actual number of recurring complaint – Target number of recurring complaint) ÷ (Total complaints)', 'Need to review repeating complaints and study to identify root cause', 1);
INSERT INTO `kpi_info` VALUES (5, 7, 1, 6, 'Effectiveness of Customer Care Centre regarding requests and complaints', 'Response Time', 'EMERGENCY – 100% within 15 minutes follow up time, URGENT – 75% response within 15 minutes with 1 hour follow up time, NORMAL – 70% within 30 minutes with 24 hours follow up', 'CMMS Work request & Complaint Work Order records', 0.100, 'Incidences of non-compliance ÷ total incidences', 'CMMS records shall indicate these records on Response Time', 1);
INSERT INTO `kpi_info` VALUES (6, 7, 1, 7, 'Availability of major services e.g water supply, power supply\r', 'Service Uptime', 'ZERO downtime of major services at 24 hours service area, 10 % (of normal working hour) downtime of major services at office area', 'CMMS & Complaint reports', 0.100, '(?GFA of excess affected areas x hours affected) ÷ (total GFA x service hours in a month)', 'So far water storage and standby gensets are available to maintain these services provisions; PPM are being executed', 1);
INSERT INTO `kpi_info` VALUES (7, 7, 1, 8, 'Availability of comfortable environment', 'Air–conditioning temperature 24`C +- 1`C DB, RH 55% +- 5%', '75 % compliance', 'CMMS & Complaint reports', 0.100, '(number of target i.e minimum WO to be done – number of actual PPM WO done) ÷ (number of PPM WO planned)\r', 'All PPMs are CLOSED within same month; system defects impede efficiencies of system', 1);
INSERT INTO `kpi_info` VALUES (8, 7, 1, 9, 'Execution of Planned Preventive Maintenance as per schedule', 'Execution of Planned Preventive Maintenance (PPM)\r', '95% execution according to schedule\r\n', 'CMMS & verification by Superintending Officer', 0.100, 'number of target ie.e minimum WO to be doen – number of actual PPM WO done) ÷ (number of PPM WO planned)\r', 'All PPMs are completed within same month, but next year schedules need to be improved, by week rather than by day', 1);
INSERT INTO `kpi_info` VALUES (9, 7, 1, 10, 'Execution of Corrective Maintenance', 'Execution Time\r', 'EMERGENCY – Rectification or mitigation time within 3 hours, URGENT – Rectification or mitigation time within 24 hours, NORMAL – Rectification or mitigation time within 7 days. 75 % of above cases to be met.', 'CMMS, complaints records & verification b PD\r', 0.100, 'Incidences of non-compliance ÷ total incidences', 'Need to study records on effectiveness on compliances; otherwise subject to deduction', 1);
INSERT INTO `kpi_info` VALUES (10, 7, 1, 11, 'Quality of Service Delivery or Workmanship', 'Unsatisfactory Executed Work', 'Below 20% monthly work order', 'CMMS & requester verification', 0.050, '(Actual number of unsatisfactory WO – Target number of unsatisfactory WO) ÷ (Total WO)', 'CMMS records are necessary to identify weaknesses', 1);
INSERT INTO `kpi_info` VALUES (11, 7, 1, 12, 'Compliance to Statutory Requirements', 'All approrpiate plants, equipment and structures shall comply with the relevant statutory Inspection schedule and requirements\r', '100% compliance', 'CMMS, permits, licenses, payments receipt & Competent Persons` reports & approvals', 0.100, 'Number of Non-Compliance ÷ total number of certification.\r\nDelays by certification bodies are exempted.', 'Engineering Dept needs to have a standard format for ease of monitoring; present ones are inconsistent', 1);
INSERT INTO `kpi_info` VALUES (12, 7, 1, 13, 'Security Service Patrols', 'Completeness of patrols and tours', '90% of agreed patrols completed', 'Clocking System Report', 0.025, '(Target Patrols = Actual Patrols Done) ÷ Total Patrols', NULL, 1);
INSERT INTO `kpi_info` VALUES (13, 7, 1, 14, 'Security Service Personnel', 'Deloyment of security guards', '80% of attendance', 'Attendance Report', 0.025, '(Target Attendance – Actual Attendance) ÷ Total Attendance', NULL, 1);
