INSERT INTO `ppm_checklist` VALUES (1, 1, 'bnm - vrv', 'M001H ', '1', 'checklist - vrv for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and make sure frequency inverter is running in \'Auto Start\'.\n', 53, 8071, '00:15:00', '00:45:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (2, 1, 'bnm - ducting', 'M001I', '1', 'checklist - ducting for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and start by BCS.\n', 54, 224486, '00:30:00', '01:00:00', NULL, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (3, 1, 'bnm - hex', 'M001J', '1', 'checklist - hex for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and start by BCS.\n', 55, 224487, '00:45:00', '01:15:00', NULL, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (4, 1, 'bnm - blast freezer', 'M001K', '1', 'checklist - blast_freezer for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and start using BCS at control room.\n', 209, NULL, NULL, NULL, NULL, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 2);
