INSERT INTO `ppm_checklist` VALUES (41, 1, 'bnm - sewerage treatment plant', 'M009A', '1', 'checklist - sewerage_treatment_plant for bnm', 'The following guidelines shall be followed:\n1.	Inform to supervisor/engineer (Civil) before carrying out the inspection exercise.\n2.	At least 2 manpower needed for this exercise to be carried out on site.\n3.	Wear basic PPE when doing the inspection.\n4.	Follow the safety requirement such as safety temporary signage, safety vest and etc.\n', 104, 7995, '00:15:00', '00:30:00', NULL, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (42, 1, 'bnm - stp pumpset seubmersible pump', 'M009B', '1', 'checklist - stp_pumpset_seubmersible_pump for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signage at the specific control panel.\n5. Reset selector switch to BMS and start by BMS (if applicable).\n', 105, 7997, NULL, NULL, NULL, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 2);
INSERT INTO `ppm_checklist` VALUES (43, 1, 'bnm - 11kV vcb', 'E001A', '1', 'checklist - 11kV_vcb for bnm', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use\nOR,\nRefer to ……………………………………\n', 20, 1916, '00:15:00', '00:45:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (44, 1, 'bnm - 11kV vcb shutdown', 'E001B', '1', 'checklist - 11kV vcb shutdown for bnm', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Inform / notice to related department/authority a week before shutdown works\n3.   Make sure the incoming supply Vacuum Circuit Breaker is totally disconnected and draw out if required\n4.   Apply Log out/Tag out safety procedure\n5.   Use proper Signboards and personal protective equipment and make sure there are two technicians are present\nOR,\nRefer to ……………………………………..\n', 21, 1917, '06:00:00', '12:00:00', 3, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (45, 1, 'bnm - 11kv ht transformer', 'E001C', '1', 'checklist - 11kV ht transformer for bnm', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use\nOR,\nRefer to ……………………………………..\n', 22, 1919, '00:15:00', '00:30:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
