INSERT INTO `ppm_checklist` VALUES (83, 1, 'bnm - projector screen conference system', 'E007B', '1', 'checklist - projector screen conference system for bnm', 'The following guidelines shall be followed:\n1.	Do not use any organic solvents for cleaning.\n2.	Do not touch the printed circuit boards with bare hands.\n3.	Use personal protective equipment.\n', 34, 7586, '00:15:00', '00:30:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
