INSERT INTO `ppm_checklist` VALUES (85, 1, 'bnm - pabx', 'E006A', '1', 'checklist - pabx for bnm', 'The following guidelines shall be followed:\n1.   Make sure proper Personal Protective Equipment is intact.\n2.   Do not wear loose clothing or jewellery while working around equipment.\n3.   Switch off the unit if maintenance activity requires adjustments, repair or etc.', 32, 8034, '00:30:00', '01:00:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (86, 1, 'bnm - bcs(nc&ddc)', 'E005A', '1', 'checklist - bcs for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications, repairs or etc. \n2. Two technicians must be present to achieve safety operations and carry out PPM.\n3. Isolate incoming power supply if required.\n', 309, 7588, '00:30:00', '01:00:00', NULL, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (87, 1, 'bnm - earthing&lightning', 'E004A', '1', 'checklist - earthing and lightning for bnm', 'The following guidelines shall be followed:\n1.   Use personal Protective Equipment.\n2.	Two technicians must be present to achieve safety operations and carry out PPM.\n', 30, 1948, '00:30:00', '00:45:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (88, 1, 'bnm - genset onload', 'E003C', '1', 'checklist - genset_onload for bnm', 'The following guidelines shall be followed:\n1. Do not wear loose clothing or jewellery while working around equipment\n2. Displays safety signage at specific control panel & follow any applicable general safety measures\n', 29, 1947, '02:00:00', '03:00:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (89, 1, 'bnm - amf board', 'E003B', '1', 'checklist - amf_board for bnm', 'The following guidelines shall be followed:\n1. Do not wear loose clothing or jewellery while working around equipment.\n2. Use personal protective equipment while carrying out PPM.   \n3. Verify all control panels are indicating \'ON\' and ensure in normal condition.\n', 28, 1946, '00:15:00', '00:30:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (90, 1, 'bnm - genset offload test', 'E003A', '1', 'checklist - genset_offload_test for bnm', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.\n3.   Displays safety signage at specific control panel & follow any applicable general safety measures.\n', 27, 1945, '00:15:00', '00:45:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (91, 1, 'bnm - feeder pillar', 'E002D', '1', 'checklist - feeder pillar for bnm', 'The following guidelines shall be followed:\n1.	Switch off the Board if maintenance activity requires adjustments, lubrications, repairs or etc.\n2.	  Two technicians must be present to achieve safety operations and carry out PPM.\n3.	 Display safety signages at specific Board during carry out PPM.\n', 26, 1924, '00:15:00', '00:30:00', 0, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (92, 1, 'bnm - lv panel(ssb/db)', 'E002C', '1', 'checklist - lv panel(ssb/db) for bnm ', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repairs. \n2. Isolate incoming power supply if required.  \n3. Display safety signages at specific control panel.\n', 199, 1923, '00:15:00', '00:30:00', 0, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (93, 1, 'bnm - lv acb shutdown', 'E002B', '1', 'checklist - lv_acb_shutdown for bnm', 'The following guidelines shall be followed:\n1.	Do not wear loose clothing or jewellery while working around equipment. \n2.	Inform / notice to relate department/authority a week before shutdown works.\n3.	Make sure the incoming supply Air Circuit Breaker is totally disconnected and draw out if required.\n4.	Apply log out/tag out safety procedure.\n5.	Use proper Signboards and personal protective equipment and make sure there are two technicians are present.\n', 24, 7622, '06:00:00', '12:00:00', 3, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (94, 1, 'bnm - lv panel msb(acb)', 'E002A', '1', 'checklist - lv_panel_msb(acb) for bnm', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.\n', 23, 1921, '00:15:00', '00:45:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (95, 1, 'bnm - cooling tower unit', 'M001G', '1', 'checklist - cooling tower unit for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and make sure frequency inverter is running in \'Auto Start\'.\n', 52, 8069, '00:45:00', '01:15:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (96, 1, 'bnm - chiller', 'M001F', '1', 'checklist - chiller for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.\n5. Reset selector switch to BCS and make sure frequency inverter is running in \'Auto Start\'.\n', 51, 8067, '00:15:00', '45:00:00', 1, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (97, 1, 'bnm - pacu', 'M001E', '1', 'checklist - pacu for bnm', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and make sure frequency inverter is running in \'Auto Start\'.\n', 50, 8064, '00:30:00', '01:00:00', NULL, '2019-07-15 12:58:24', '2019-07-15 12:57:02', 1, 1);
