INSERT INTO `ppm_checklist` VALUES (153, 1, 'bnmhq - 11kv-ht transformer block ab', 'E001C', '1', 'checklist - 11kV ht_transformer raisin', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use\n4.   Use proper personal protective equipment', 22, 7613, '00:15:00', '00:30:00', 1, '2019-09-01 20:40:06', '2019-09-01 20:23:37', 8, 1);
