INSERT INTO `ppm_checklist` VALUES (234, 1, 'bnmdc - amf board', 'E003B', '1', 'checklist - amf_board for bnmdc', 'The following guidelines shall be followed:\n1. Do not wear loose clothing or jewellery while working around equipment.\n2. Use personal protective equipment while carrying out PPM.   \n3. Verify all control panels are indicating ‘ON’ and ensure in normal condition.\nOR,\n Refer to ……………………….', 177, 7609, '00:15:00', '00:30:00', 1, '2019-10-18 15:33:43', '2019-10-18 15:17:10', 1, 1);
