INSERT INTO `ppm_checklist` VALUES (270, 1, 'bnmsk - feeder pillar', 'E002D', '1', 'checklist - feeder pillar for bnmsk', 'The following guidelines shall be followed:\n1.	Make sure the Personal Protective Equipment is intact.   \n2.	Switch off the panel if maintenance activity requires adjustments, lubrications, repairs or etc.\n3.	Two technicians must be present to achieve safety operations and carry out PPM.\n4.	Display safety signage at specific panel during PPM.', 26, 385, '00:15:00', '00:45:00', 1, '2019-10-31 20:16:48', '2019-10-31 20:03:29', 1, 1);
