INSERT INTO `ppm_checklist` VALUES (356, 1, 'bnmdc - hose reel drum(monitor vendor)', 'M003O ', '1', 'checklist - hose reel drum for bnmdc', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.', 81, 225150, '00:02:00', '00:05:00', 0, '2019-12-24 10:21:57', '2019-12-24 10:18:57', 1, 1);
INSERT INTO `ppm_checklist` VALUES (357, 1, 'bnmdc - fire extinguisher(monitor vendor)', 'M003B', '1', 'checklist - fire extinguisher for bnmdc', 'The following guidelines shall be followed:\n1.	Ensure extinguishers and cylinders are in their correct location\n2.	Isolate all isolation switches at panel and disconnect wiring\n3.	To weigh the cylinder, disconnect the system piping from the discharge actuator valve. Remove the cylinder with their actuator valves \n        intact and weigh them.\n4.	Set value is the total weight for each extinguisher/cylinder including the gas/dry powder and intact accessories.', 211, NULL, NULL, NULL, NULL, '2019-12-24 10:45:41', '2019-12-24 10:43:13', 1, 1);
INSERT INTO `ppm_checklist` VALUES (359, 1, 'bnmdc - hose reel pump(monitor vendor)', 'M003D', '1', 'checklist - hose reel pump for bnmdc', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.', 71, 20906, '00:30:00', '01:00:00', 1, '2019-12-24 13:39:11', '2019-12-24 13:36:52', 1, 1);
INSERT INTO `ppm_checklist` VALUES (360, 1, 'bnmdc - sprinkler system(minitor vendor)', 'M003F', '1', 'checklist - sprinkler syetem for bnmdc', 'The following guidelines shall be followed:\n1. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n2. Check and double confirm there is no electricity in the starter panel nor in the unit.\n3. Display safety signages at specific control panel.\n4. Ensure the test valve is closed and the alarm control valve is reopened when testing is complete and system restored to service.', 73, 225164, '00:30:00', '01:00:00', 1, '2019-12-24 13:46:55', '2019-12-24 13:44:46', 1, 1);
