INSERT INTO `ppm_checklist` VALUES (363, 1, 'bnmhq - waste water pump', 'M002B', '1', 'checklist - waste water pump for bnmhq', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signage at the specific control panel.\n5. Reset selector switch to BMS and start by BMS (if applicable).', 318, 130673, '00:30:00', '01:00:00', 1, '2020-01-09 12:35:37', '2020-01-09 12:27:30', 1, 1);
INSERT INTO `ppm_checklist` VALUES (364, 1, 'matrade - roads,hard-shoulders,footpaths,road furniture&signage', 'C001A', '1', 'checklist - roads, hard-shoulders, footpaths, road furniture & signage for matrade', 'The following guidelines shall be followed:\n1.	Must wear safety vest to aware road user.\n2.	Use proper and suitable personal protective equipment.\n3.	Barricade the area of road under maintenance.\n4.	Refer SDS for emergency guidelines during any renewal road marking works', 1, NULL, NULL, NULL, NULL, '2020-01-30 15:05:37', '2020-01-12 21:09:06', 1, 1);
INSERT INTO `ppm_checklist` VALUES (365, 1, 'matrade - fencing&gates', 'C001B', '1', 'checklsit - fencing and gates for matrade', 'The following guidelines shall be followed:\n1.	Barricade the defects area by using red-white tape. \n2.	Use proper and suitable personal protective equipment (renew finishes).\n3.	Refer SDS for emergency guidelines during any renewal finishes works.', 3, NULL, NULL, NULL, NULL, '2020-01-30 15:05:50', '2020-01-12 21:13:47', 1, 1);
INSERT INTO `ppm_checklist` VALUES (366, 1, 'matrade - tank', 'C002A', '1', 'checklist - tank for matrade', 'The following guidelines shall be followed:\n1.	Ensure there is competent person (internal or sub-contractor representative monitoring) for confined space.\n2.	Use proper and suitable personal protective equipment.\n3.	Put the signage ‘DANGER: CONFINED SPACE. DO NOT ENTERS’\n4.	Ensure to blow the air out before maintaining work start. \n5.	Ensure the technicians are aware of the hazards/ aspect and well-trained job.\n6.	Used buddy system.', 248, NULL, NULL, NULL, NULL, '2020-01-30 15:06:23', '2020-01-12 21:17:03', 1, 1);
INSERT INTO `ppm_checklist` VALUES (367, 1, 'matrade - drains,sumps,gratingandculvert', 'C003A', '1', 'checklist - drains, sumps, grating and culvert for matrade', 'The following guidelines shall be followed:\n1.	Use proper and suitable personal protective equipment.\n2.	Removes all solid foreign material by using proper tools.', 7, NULL, NULL, NULL, NULL, '2020-01-30 14:56:21', '2020-01-13 08:00:55', 1, 1);
INSERT INTO `ppm_checklist` VALUES (369, 1, 'matrade - plumbing & sanitary system', 'C003B', '1', 'checklist - plumbung and sanitary system', 'The following guidelines shall be followed:\n1.	Display safety signage at specific defects toilet or area. \n2.	Use 3 steps ladder while inspect/maintaining the plumbing and sanitary system.\n3.	Use proper and suitable personal protective equipment.', 5, NULL, NULL, NULL, NULL, '2020-01-30 14:55:59', '2020-01-13 08:03:48', 1, 1);
