INSERT INTO `ppm_checklist` VALUES (371, 1, 'matrade - rainwater down pipe goods', 'C003D', '1', 'checklist - rainwater down pipe goods for matrade', 'The following guidelines shall be followed:\n1.	Display safety signage at specific defects toilet or area. \n2.	Use 3 steps ladder while inspect/maintaining the RWDP.\n3.	Use proper and suitable personal protective equipment.\n4.	Ensure that there is temporary good light and good ventilation within the working area.\n5.	Make sure working area were in maximum cleanliness after services works.', 6, NULL, NULL, NULL, NULL, '2020-01-30 14:56:11', '2020-01-13 08:08:17', 1, 1);
