INSERT INTO `ppm_checklist` VALUES (387, 1, 'matrade - ht panel 11KV(gcb)-TX', 'E001A', '1', 'checklist - ht panel 11kv for matrade', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use\n4.   Use proper personal protective equipment and make sure there are two technicians are present', 268, 11240, NULL, NULL, NULL, '2020-01-31 11:43:32', '2020-01-13 09:41:16', 1, 1);
INSERT INTO `ppm_checklist` VALUES (388, 1, 'matrade - ahu', 'M001A ', '1', 'AHU_Matrade', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.\n5. Reset selector switch to BCS and make sure frequency inverter is running in ‘Auto Start’\n6. Use proper and suitable personal protective equipment.\n', 41, 11199, NULL, NULL, NULL, '2020-01-31 09:46:35', '2020-01-13 09:42:45', 1, 1);
INSERT INTO `ppm_checklist` VALUES (389, 1, 'matrade - ht panel 11KV (GCB) (shutdown)', 'E001B', '1', 'checklist - HT Panel 11KV (GCB) (Shutdown)', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Inform / notice to related department/authority a week before shutdown works\n3.   Make sure the incoming supply Vacuum Circuit Breaker is totally disconnected and draw out if required\n4.   Apply Log out/Tag out safety procedure\n5.   Use proper Signboards and personal protective equipment and make sure there are two technicians are present\n', 21, NULL, NULL, NULL, NULL, '2020-05-12 17:42:27', '2020-01-13 11:21:37', 1, 1);
