INSERT INTO `ppm_checklist` VALUES (409, 1, 'matrade - generator set(ON Load Test)', 'E003C', '1', 'checklist - generetor set(ON Load Test) for matrade', 'The following guidelines shall be followed:\n1. Do not wear loose clothing or jewellery while working around equipment\n2. Displays safety signage at specific control panel & follow any applicable general safety measures\n3. Wear required/proper PPE such as safety shoes, safety vest and safety helmet', 177, NULL, NULL, NULL, NULL, '2020-01-13 18:14:36', '2020-01-13 18:04:29', 1, 1);
INSERT INTO `ppm_checklist` VALUES (410, 1, 'matrade - amf board', 'E003B', '1', 'checklist - amf board for matrade', 'The following guidelines shall be followed:\n1. Do not wear loose clothing or jewellery while working around equipment.\n2. Use personal protective equipment while carrying out PPM.   \n3. Verify all control panels are indicating ‘ON’ and ensure in normal condition.\n4. Wear required/proper PPE such as safety shoes, safety vest and safety helmet.', 28, NULL, NULL, NULL, NULL, '2020-01-13 18:25:20', '2020-01-13 18:15:18', 1, 1);
INSERT INTO `ppm_checklist` VALUES (411, 1, 'matrade - generator set(off load test)', 'E003A', '1', 'checklist - generator set(off load test) for matrade', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.\n3.   Displays safety signage at specific control panel & follow any applicable general safety measures\n4.   Wear required/proper PPE such as safety shoes, safety vest and safety helmet.\n', 177, NULL, NULL, NULL, NULL, '2020-01-13 18:38:03', '2020-01-13 18:27:33', 1, 1);
INSERT INTO `ppm_checklist` VALUES (412, 1, 'matrade - main fire alarm panel', 'M007A', '1', 'checklist - main fire alarm panel for matrade', 'The following guidelines shall be followed :\n     1. Disable Master Zone before carrying out maintenance activities.\n     2. Test smoke detector either by using artificial smoke spray or test magnet.\n     3. Upon completion of the activities, make sure that all systems are set to normal mode.\n     4. Use proper and suitable personal protective equipment.\n', 66, 15790, NULL, NULL, NULL, '2020-01-31 09:35:37', '2020-01-13 18:38:19', 1, 2);
