INSERT INTO `ppm_checklist` VALUES (419, 1, 'matrade - lv panel - msb (acb)(shutdown )', 'E002B', '1', 'checklist - v panel - msb (acb)(shutdown ) for matrade', 'The following guidelines shall be followed:\n1.	Do not wear loose clothing or jewellery while working around equipment. \n2.	Inform / notice to related department/authority a week before shutdown works.\n3.	Make sure the incoming supply Air Circuit Breaker is totally disconnected and draw out if required.\n4.	Apply log out/tag out safety procedure.\n5.	Use proper Signboards and personal protective equipment and make sure there are two technicians are present.', 24, NULL, NULL, NULL, NULL, '2020-01-13 19:58:41', '2020-01-13 19:22:45', 1, 1);
