INSERT INTO `ppm_checklist` VALUES (438, 1, 'uorm - generator onload test', 'E003B', '1', 'checklist - generator(onload test) for uorm', 'The following guidelines shall be followed:\n1.	Ensure availability of circuit diagram, safety chart, first aid kit, danger sign, fire extinguisher and rubber mat.\n2.	Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.\n3.	Do not wear loose clothing or jewellery while working around equipment.\n4.	Apply lock out / tag out procedures.\n5.	Use appropriate PPE.', 29, NULL, NULL, NULL, NULL, NULL, '2020-01-16 14:50:48', NULL, 5);
INSERT INTO `ppm_checklist` VALUES (439, 1, 'uorm - pest control service', 'PM001', '1', NULL, 'The following guidelines shall be followed:														\n1.  To check Monthly Schedule activity														\n2.  To use proper PPE														\n3.  To use proper signage, equipment and machinery														\n4.   PM task need to monitor by supervisor														\n', 338, 33158, NULL, NULL, NULL, '2020-01-21 15:04:38', '2020-01-21 14:59:37', 1, 1);
