INSERT INTO `ppm_checklist` VALUES (500, 1, 'perkeso - earthing & lightning system', 'E004A', '1', 'checklist - earthing & lightning system for perkeso', 'The following guidelines shall be followed:\n1.   Use personal Protective Equipment.\n2.	Two technicians must be present to achieve safety operations and carry out PPM.\nOR,\nRefer to …………………….', 30, 235268, '00:30:00', '00:45:00', 1, '2020-07-17 11:52:31', '2020-02-06 13:50:33', 1, 1);
INSERT INTO `ppm_checklist` VALUES (501, 1, 'perkeso - generator set(on load test)', 'E005A', '1', 'checklist - generator(on load test) for perkeso', 'The following guidelines shall be followed:\n1.	Ensure availability of circuit diagram, safety chart, first aid kit, danger sign, fire extinguisher and rubber mat.\n2.	Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.\n3.	Do not wear loose clothing or jewellery while working around equipment.\n4.	Apply lock out / tag out procedures.\n5.	Use proper Personal Protective Equipment (PPE).\n', 29, 16694, '02:00:00', '03:00:00', 1, '2020-07-17 11:38:26', '2020-02-06 13:50:33', 1, 1);
