INSERT INTO `ppm_checklist` VALUES (503, 1, 'perkeso - generator set(off load test)', 'E003A', '1', 'checklist - generator(off load test) for perkeso', 'The following guidelines shall be followed:\n1.	Ensure availability of circuit diagram, safety chart, first aid kit, danger sign, fire extinguisher and rubber mat.\n2.	Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.\n3.	Do not wear loose clothing or jewellery while working around equipment.\n4.	Apply lock out / tag out procedures.\n5.	Use proper Personal Protective Equipment (PPE).\n', 27, 228813, '00:15:00', '00:45:00', 1, '2020-07-17 11:33:51', '2020-02-06 13:50:33', 1, 1);
