INSERT INTO `ppm_checklist` VALUES (579, 1, 'ppns - main fire alarm panel', 'M003A', '1', NULL, 'The following guidelines shall be followed:\n     1. Disable Master Zone before carrying out maintenance activities\n     2. Test smoke detector either by using artificial smoke spray or test magnet\n     3. Upon completion of the activities, make sure that all systems are set to normal mode', 66, 67409, '00:30:00', '01:00:00', NULL, '2020-03-17 13:34:06', '2020-03-17 13:04:03', 1, 1);
