INSERT INTO `ppm_checklist` VALUES (581, 1, 'lkim - dry powder', 'M005B', '1', NULL, 'The following guidelines shall be followed:\n1.	Ensure extinguishers and cylinders are in their correct location\n2.	Isolate all isolation switches at panel and disconnect wiring\n3.	To weigh the cylinder, disconnect the system piping from the discharge actuator valve. Remove the cylinder with their actuator valves intact and weigh them.\n4.	Set value is the total weight for each extinguisher/cylinder including the gas/dry powder and intact accessories.\n', 211, 26837, NULL, NULL, NULL, '2020-03-19 10:49:27', '2020-03-17 14:45:55', 1, 1);
INSERT INTO `ppm_checklist` VALUES (582, 1, 'bnmsk - ahu', 'M001A', '1', 'checklist - ahu for bnmsk', 'The following guidelines shall be followed:\n1.	Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2.	Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3.	Check and double confirm there is no electricity in the starter panel nor in the unit.\n4.	Display safety signages at the specific control panel.\n5.	Reset selector switch to BCS and make sure frequency inverter is running in \'Auto Start\'.', 41, 211422, '00:15:00', '00:45:00', 1, '2020-03-18 23:15:45', '2020-03-18 22:53:35', 1, 1);
INSERT INTO `ppm_checklist` VALUES (583, 1, 'bnmtk - lighting system', 'E010C', '1', 'checklist - lighting system for bnm TK', 'The following guidelines shall be followed:\n1.   Follow OSHA safe work procedure\n2.   \n', 40, 143416, '00:15:00', '00:30:00', 1, '2020-03-21 00:03:41', '2020-03-20 23:56:11', 1, 1);
