INSERT INTO `ppm_checklist` VALUES (634, 1, 'educity - rodent control', 'PC001B', '1', 'checklist - rodent control for educity', 'The following guidelines shall be followed:														\n1.  To check Monthly Schedule activity														\n2.  To use proper PPE														\n3.  To use proper signage, equipment and machinery														\n4.   PM task need to monitor by supervisor		', 432, 49448, NULL, NULL, NULL, '2020-04-14 22:44:53', '2020-04-14 22:40:11', 1, 1);
INSERT INTO `ppm_checklist` VALUES (635, 1, 'matrade - generator set(off load test)', 'E003A', '1', NULL, 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.\n3.   Displays safety signage at specific control panel & follow any applicable general safety measures\n4.   Wear required/proper PPE such as safety shoes, safety vest and safety helmet.\n', 27, NULL, NULL, NULL, NULL, '2020-04-15 10:55:41', '2020-04-15 10:44:51', 1, 1);
INSERT INTO `ppm_checklist` VALUES (636, 1, 'educity - db', 'E001C', '1', 'checklist pm for ssb/db', 'The following guidelines shall be followed:\n1.	Make sure the Personal Protective Equipment is intact.   \n2.	Switch off the panel if maintenance activity requires adjustments, lubrications, repairs or etc.\n3.	Two technicians must be present to achieve safety operations and carry out PM.\n4.	Display safety signage at specific panel during PM.', 301, 35647, '00:15:00', '00:30:00', 0, '2020-04-30 15:15:06', '2020-04-20 14:44:29', 522, 1);
INSERT INTO `ppm_checklist` VALUES (654, 1, 'educity - msb(m)', 'E001A', '1', 'checklist educity - Main Switch Board ', 'The following guidelines shall be followed:\n1.   Make sure proper Personal Protective Equipment is intact.\n2.   Do not wear loose clothing or jewellery while working around equipment.\n3.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n4.   Make sure all gates, doors or other devices leading to the HV zones shall be kept locked after in use.', 300, 35642, '00:15:00', '00:45:00', 1, '2020-04-30 15:16:00', '2020-04-23 09:50:40', 522, 1);
INSERT INTO `ppm_checklist` VALUES (655, 1, 'educity - msb(y)', 'E001B', '1', 'Checklist educity - Main Switch Board (Shutdown) ', 'The following guidelines shall be followed:\n1.	Advance notice on shutdown has been sent to effected department.\n2.	Do not wear loose clothing or jewellery while working around equipment.\n3.	Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n4.	Make sure all gates, doors or other devices leading to High Voltage Zone shall be kept locked after in use.\n5.	Make sure the Personal Protective Equipment is intact.', 300, 38063, '01:00:00', '03:00:00', 2, '2020-04-30 15:16:46', '2020-04-23 10:11:43', 522, 1);
INSERT INTO `ppm_checklist` VALUES (656, 1, 'educity - signboard', 'C001A', '1', 'checklist pm for signboard', 'The following guidelines shall be followed:\n1. Wear basic PPE when do the inspection\n2. At least 2 personnel carry out the inspection.\n3. Divert the traffic flow if necessary\n4. Follow the safety requirement such as safety temporary signage, flag-man, safety vest and etc.\n', 398, NULL, NULL, NULL, NULL, '2020-04-23 11:06:52', '2020-04-23 10:25:34', 1, 1);
INSERT INTO `ppm_checklist` VALUES (657, 1, 'educity - cold water storage tank', 'C002A', '1', 'checklist pm for cold water storage tank (Q)', 'The following guidelines shall be followed:\n1. Do not enter the tank for 15 min after open the tank manhole access\n2. Bring along the torch light for checking the inner tank area \n3. This exercise must be carried at least with 2 manpower and knowing by the supervisor\n4. Wear basic PPE when do the inspection\n5. Follow the safety requirement such as safety temporary signage, flag-man, safety vest and etc.', 397, 41218, NULL, NULL, NULL, '2020-04-23 10:31:01', '2020-04-23 10:25:56', 1, 1);
INSERT INTO `ppm_checklist` VALUES (658, 1, 'educity - domestic water tank', 'C002A', '1', 'checklist pm for domestic water tank', 'The following guidelines shall be followed:\n1. Do not enter the tank for 15 min after open the tank manhole access\n2. Bring along the torch light for checking the inner tank area \n3. This exercise must be carried at least with 2 manpower and knowing by the supervisor\n4. Wear basic PPE when do the inspection\n5. Follow the safety requirement such as safety temporary signage, flag-man, safety vest and etc.\n', 396, 41217, NULL, NULL, NULL, '2020-04-23 10:38:18', '2020-04-23 10:32:12', 1, 1);
INSERT INTO `ppm_checklist` VALUES (659, 1, 'educity - parameter safety fencing ', 'C001B', '1', 'checklist pm for parameter safety fencing', 'The following guidelines shall be followed:\n1. Wear basic PPE when do the inspection\n2. At least 2 personnel carry out the inspection.\n3. Divert the traffic flow if necessary\n4. Follow the safety requirement such as safety temporary signage, flag-man, safety vest and etc.\n', 399, 35634, NULL, NULL, NULL, '2020-04-23 10:48:13', '2020-04-23 10:40:38', 1, 1);
INSERT INTO `ppm_checklist` VALUES (660, 1, 'educity - grease trap', 'C003A', '1', 'checklist pm for grease trap', 'The following guidelines shall be followed:\n1.  Wear basic PPE when do the inspection\n2.  Follow the safety requirement such as safety temporary signage, safety vest and etc.\n', 196, 41216, NULL, NULL, NULL, '2020-04-23 10:58:50', '2020-04-23 10:54:40', 1, 1);
