INSERT INTO `ppm_checklist` VALUES (662, 1, 'educity - capacitor bank', 'E002D', '1', 'Checklist educity - Capacitor Bank', 'The following guidelines shall be followed:\n1.   Make sure proper Personal Protective Equipment is intact.\n2.   Do not wear loose clothing or jewellery while working around equipment.\n3.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n4.   Make sure all gates, doors or other devices leading to the zones shall be kept locked after in use.\n', 371, 51163, '00:15:00', '00:30:00', 1, '2020-04-30 15:17:21', '2020-04-23 12:53:02', 522, 1);
INSERT INTO `ppm_checklist` VALUES (663, 1, 'educity - feeder pillar', 'E001D', '1', 'Checklist educity - Feeder Pillar', 'The following guidelines shall be followed:\n1.	Make sure the Personal Protective Equipment is intact.   \n2.	Switch off the panel if maintenance activity requires adjustments, lubrications, repairs or etc.\n3.	Two technicians must be present to achieve safety operations and carry out PPM.\n4.	Display safety signage at specific panel during PPM.', 26, 35646, '00:15:00', '00:45:00', 1, '2020-04-30 15:17:51', '2020-04-23 12:53:09', 522, 1);
INSERT INTO `ppm_checklist` VALUES (664, 1, 'educity - fireman switch(tap off)', 'E001F', '1', 'Checklist educity - Fireman switch / Tap OFF Unit', 'The following guidelines shall be followed:\n1.	Inform the relevant Department during each visit and obtain approval.\n2.	Ensure all keys for locked rooms are available at the time of inspection.\n3.	Use personal protective equipment\n4.	Two technicians must be present to achieve safety operations and carry out PM.', 349, 38064, NULL, NULL, NULL, '2020-04-30 15:18:46', '2020-04-27 09:11:49', 522, 1);
