INSERT INTO `ppm_checklist` VALUES (666, 1, 'educity - high mast lighting', 'E001E', '1', 'Checklist educity - High Mast', 'The following guidelines shall be followed:\n1.    Switch off the control panel if maintenance activity requires adjustments, lubrications, repairs or etc.\n2.	Minimum 3 competent technicians must be present to achieve safety operations and carry out PPM.\n3.	Display safety signage at specific feeder pillar during carry out PPM.\n4.	Use safety gears such as, helmets, boots, harness belt etc.', 418, 35644, '01:00:00', '03:00:00', 2, '2020-04-30 15:19:23', '2020-04-27 09:21:45', 522, 1);
INSERT INTO `ppm_checklist` VALUES (667, 1, 'educity - genset(offload test)', 'E002A', '1', 'Checklist educity - OFF Load Test', 'The following guidelines shall be followed:\n1.	Ensure availability of circuit diagram, safety chart, first aid kit, danger sign, fire extinguisher and rubber mat.\n2.	Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.\n3.	Do not wear loose clothing or jewellery while working around equipment.\n4.	Apply lock out / tag out procedures.\n5.	Use appropriate PPE.', 177, 45874, '00:30:00', '01:00:00', 1, '2020-04-30 15:20:12', '2020-04-27 09:34:45', 522, 1);
