INSERT INTO `ppm_checklist` VALUES (681, 1, 'educity - C02 extinguisher', 'M003B', '1', 'checklist - C02 Extinguisher for educity', 'The following guidelines shall be followed:\n1.	Ensure extinguishers and cylinders are in their correct location\n2.	Isolate all isolation switches at panel and disconnect wiring\n3.	To weigh the cylinder, disconnect the system piping from the discharge actuator valve. Remove the cylinder with their actuator valves intact and weigh them.\n4.	Set value is the total weight for each extinguisher/cylinder including the gas/dry powder and intact accessories.', 361, 225053, '00:02:00', '00:05:00', 0, '2020-05-11 22:22:15', '2020-05-11 22:06:21', 1, 1);
INSERT INTO `ppm_checklist` VALUES (682, 1, 'educity - pyroshield', 'M003B', '1', 'checklist - pyroshield for educity', 'The following guidelines shall be followed:\n1. Use PPE like breathing apparatus,eye goggles disposable gloves and apron,safety shoes etc as applicable\n2. Inform Emergency & Crisis Management that maintenance activity is being carried out', 409, NULL, NULL, NULL, NULL, '2020-05-11 22:43:36', '2020-05-11 22:34:24', 1, 1);
INSERT INTO `ppm_checklist` VALUES (683, 1, 'educity - fire rated door', 'M003M', '1', 'checklist - fire rated door for educity', 'The following guidelines shall be followed:\n1.  Wears basic PPE\n2.  Use a proper ladder\n3.  Follow the safety requirement such as safety temporary signage, safety vest and etc.', 405, NULL, NULL, NULL, NULL, '2020-05-11 22:57:31', '2020-05-11 22:52:48', 1, 1);
INSERT INTO `ppm_checklist` VALUES (684, 1, 'educity - hose reel pump (duty) ', 'M003D', '1', 'checklist - hose reel pump duty for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.', 406, 117045, '00:30:00', '01:00:00', 1, '2019-09-01 14:17:33', '2019-09-01 14:10:21', 1, 1);
INSERT INTO `ppm_checklist` VALUES (685, 1, 'educity - hose reel pump (standby) ', 'M003D', '1', 'checklist - hose reel pump standby for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.', 407, 117044, '00:30:00', '01:00:00', 1, '2019-09-01 14:17:33', '2019-09-01 14:10:21', 1, 1);
INSERT INTO `ppm_checklist` VALUES (686, 1, 'educity - sprinkler pump (duty) ', 'M003D', '1', 'checklist - hose reel pump duty for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.', 412, 38530, '00:30:00', '01:00:00', 1, '2019-09-01 14:17:33', '2019-09-01 14:10:21', 1, 1);
INSERT INTO `ppm_checklist` VALUES (687, 1, 'educity - sprinkler pump (standby) ', 'M003D', '1', 'checklist - hose reel pump standby for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.', 411, 225098, '00:30:00', '01:00:00', 1, '2019-09-01 14:17:33', '2019-09-01 14:10:21', 1, 1);
INSERT INTO `ppm_checklist` VALUES (688, 1, 'educity - sprinkler pump (jockey) ', 'M003D', '1', 'checklist - hose reel pump standby for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.', 413, 35827, '00:30:00', '01:00:00', 1, '2019-09-01 14:17:33', '2019-09-01 14:10:21', 1, 1);
INSERT INTO `ppm_checklist` VALUES (689, 1, 'educity - fire hydrant', 'M003G', '1', 'checklist - fire hydrant for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.\n5. Reset selector switch to BCS and start using BCS at control room.', 77, 225243, '00:05:00', '00:10:00', 0, '2020-05-12 01:03:46', '2020-05-12 01:01:58', 1, 1);
INSERT INTO `ppm_checklist` VALUES (690, 1, 'matrade - ht panel 11KV (GCB) (shutdown) yearly', 'E001B', '1', 'checklist - HT Panel 11KV (GCB) (Shutdown)', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Inform / notice to related department/authority a week before shutdown works\n3.   Make sure the incoming supply Vacuum Circuit Breaker is totally disconnected and draw out if required\n4.   Apply Log out/Tag out safety procedure\n5.   Use proper Signboards and personal protective equipment and make sure there are two technicians are present\n', 268, NULL, NULL, NULL, NULL, '2020-05-14 17:00:09', '2020-05-12 15:10:07', 1, 1);
INSERT INTO `ppm_checklist` VALUES (691, 1, 'educity - booster pump', 'M002A', '1', 'checklist - booster pump for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.\n5. Wear the suitable PPE.\n', 332, 117042, NULL, NULL, NULL, '2020-05-13 00:23:04', '2020-05-13 00:20:06', 1, 1);
