INSERT INTO `ppm_checklist` VALUES (806, 1, 'ppns - cool/chiller room system', 'M002K', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.\n5. Reset selector switch to BMS and start using BMS at control room.\n6. Wear complete PPE.\n7. Ensure no interruption for resident user during works carry out.\n8. Provide protection for any equipment before service to avoid from damaged or dirty.', 368, 224932, '00:15:00', '00:45:00', 1, '2020-09-03 16:32:08', '2020-09-03 16:16:23', 1, 1);
INSERT INTO `ppm_checklist` VALUES (807, 1, 'ppns - mechanical asset', 'M002L', '1', NULL, 'The following guidelines shall be followed:\n1.	Inform the relevant Department during each visit and obtain approval.\n2.	Ensure all keys for locked rooms are available at the time of inspection.\n3.	Use personal protective equipment\n4.	Use torch light', 459, NULL, NULL, NULL, NULL, '2020-09-03 16:45:58', '2020-09-03 16:42:31', 1, 1);
INSERT INTO `ppm_checklist` VALUES (808, 1, 'ppns,-cold water/make-up/fire fighting tank', 'M002M', '1', NULL, 'The following guidelines shall be followed:\n    1. Inform Mechanical Competent Personnel. \n1. Do not enter the tank for 15 min after open the tank manhole access\n2. Bring along the torch light for checking the inner tank area \n3. This exercise must be carried at least with 2 manpower and knowing by the supervisor\n4. Wear basic PPE when do the inspection\n5. Follow the safety requirement such as safety temporary signage, flag-man, safety vest and etc.\n', 203, 224516, '00:15:00', '00:30:00', NULL, '2020-09-03 17:00:33', '2020-09-03 16:52:51', 1, 1);
INSERT INTO `ppm_checklist` VALUES (809, 1, 'ppns - fireman intercom', 'M003B', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signage at specific control panel.\n', 76, 225369, '00:15:00', '00:30:00', NULL, '2020-09-04 09:35:45', '2020-09-04 09:08:25', 1, 1);
INSERT INTO `ppm_checklist` VALUES (810, 1, 'ppns - wet riser system(riser room)', 'M003C', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signage at specific control panel.\n', 78, NULL, NULL, NULL, NULL, '2020-09-04 09:44:03', '2020-09-04 09:38:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (811, 1, 'ppns - hose reel', 'M003D', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signage at specific control panel.', 294, 225140, '00:05:00', '00:15:00', 0, '2020-09-04 09:50:17', '2020-09-04 09:46:05', 1, 1);
INSERT INTO `ppm_checklist` VALUES (812, 1, 'perkeso - hydrant system', 'M007F', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and start using BCS at control room.\n', 77, 225245, '00:05:00', '00:15:00', 0, '2020-09-08 14:20:51', '2020-09-04 09:59:41', 1, 1);
INSERT INTO `ppm_checklist` VALUES (813, 1, 'ppns - hydrant system', 'M003F', '1', NULL, 'The following guidelines shall be followed :\n1. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n2. Check and double confirm there is no electricity in the starter panel nor in the unit.\n3. Display safety signages at specific control panel.\n4. Ensure the test valve is closed and the alarm control valve is reopened when testing is complete and system restored to service.\n', 77, 225246, '00:30:00', '01:00:00', 1, '2020-09-04 17:34:41', '2020-09-04 09:59:55', 1, 1);
INSERT INTO `ppm_checklist` VALUES (814, 1, 'ppns - roller shutter - glass door', 'M006A', '1', 'checklist - roller shutter and glass door for ppns', 'The following guidelines shall be followed:\n1. To switch off/lock main isolator or MCCB\n2. To check no power supply at control panel\n3. To use proper signage on electrical panel\n4. To use proper safety attire hen working on high levels\n5. Never test drives when men are still working in the vicinity of the drives', 85, 224953, '00:15:00', '00:30:00', 1, '2020-09-04 14:56:52', '2020-09-04 14:51:01', 1, 1);
INSERT INTO `ppm_checklist` VALUES (815, 1, 'ppns - gondola', 'M006D', '1', 'checklist - gondola for ppns', 'The following guidelines shall be followed:\n1.	To switch off/lock main isolator or MCCB\n2.	To check no power supply at control panel \n3.	To use proper signage on electrical panels\n4.	To use proper safety attire when working on high levels\n5.	Never test drives when men are still working in the vicinity of the drives', 460, 225375, '00:30:00', '01:30:00', NULL, '2020-09-04 15:27:47', '2020-09-04 15:25:18', 1, 1);
INSERT INTO `ppm_checklist` VALUES (816, 1, 'ppns - traffic barrier gate', 'M006E', '1', 'checklist - traffic barrier gate for ppns', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signage at specific control panel.\n5. Closed the lane if any test to do for barrier gate. (If necessary) ', 461, 251831, '00:15:00', '00:30:00', 1, '2020-09-04 15:41:06', '2020-09-04 15:33:20', 1, 1);
INSERT INTO `ppm_checklist` VALUES (817, 1, 'ppns - lpg', 'M007A', '1', 'checklist - lpg for ppns', 'The following guidelines shall be followed:\n1)	Wear Protection Personal Equipment (PPE).', 95, NULL, NULL, NULL, NULL, '2020-09-04 15:48:12', '2020-09-04 15:46:12', 1, 1);
INSERT INTO `ppm_checklist` VALUES (818, 1, 'ppns - nc - ddc -mig - ups', 'M008A', '1', 'checklist - nc, ddc, mig, ups for ppns', 'The following guidelines shall be followed:\n1.	Make sure proper Personal Protective Equipment is intact.\n2.	Do not wear loose clothing or jewellery while working around equipment.\n3.	Switch off the unit if maintenance activity requires adjustments, repair or etc.', 1279, 224950, '00:30:00', '01:00:00', NULL, '2020-09-04 17:36:54', '2020-09-04 15:50:20', 1, 1);
INSERT INTO `ppm_checklist` VALUES (819, 1, 'ppns - Chilled Water, Cold Booster, Fountain, Sump, Condenser Water, Flush Pump', 'M004A', '1', 'checklist - chilled water, cold booster, fountain, sump, condenser water, flush pump for ppns', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.\n5. Reset selector switch to BMS and start by BMS', 210, 225029, '00:30:00', '01:00:00', 1, '2020-09-04 16:36:07', '2020-09-04 16:15:11', 1, 1);
INSERT INTO `ppm_checklist` VALUES (820, 1, 'ppns - sprinkler, hose reel, wet riser pump room', 'M003G', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signage at specific control panel.\n', 79, 225121, '00:30:00', '01:00:00', 1, '2020-09-04 17:52:33', '2020-09-04 17:38:14', 1, 1);
INSERT INTO `ppm_checklist` VALUES (822, 1, 'ppns - wet chemical system', 'M003I', '1', NULL, 'The following guidelines shall be followed:\n 1. Isolate all Buzzer, Bell and Gas Discharge isolation switches\n      2. Display safety signage at specific control panel.\n      3. Fire curtain, solenoid actuator and plunger must be fix to normal position after testing completed.', 231, NULL, NULL, NULL, NULL, '2020-09-06 23:25:03', '2020-09-06 23:11:56', 1, 1);
INSERT INTO `ppm_checklist` VALUES (823, 1, 'ppns - pyrogen', 'M003J', '1', 'Argonite/Pyrogen', 'The following guidelines shall be followed:\n1.	Isolate all buzzer, bell and gas discharge isolation switches.   \n2.	Display safety signage at specific control panel.\n3.	Fire curtain, solenoid actuator and plunger must be fix to normal position after testing completed.\n', 436, 130292, '00:30:00', '01:00:00', NULL, '2020-09-07 00:37:31', '2020-09-06 23:27:31', 1, 1);
INSERT INTO `ppm_checklist` VALUES (824, 1, 'ppns - fire extinguisher', 'M003K', '1', NULL, 'The following guidelines shall be followed:\n1.	Ensure extinguishers and cylinders are in their correct location\n2.	Isolate all isolation switches at panel and disconnect wiring\n3.	To weigh the cylinder, disconnect the system piping from the discharge actuator valve. Remove the cylinder with their actuator valves intact and weigh them.\n4.	Set value is the total weight for each extinguisher/cylinder including the gas/dry powder and intact accessories.\n', 464, 225062, '00:02:00', '00:05:00', 0, '2020-09-07 00:54:09', '2020-09-07 00:47:54', 1, 1);
INSERT INTO `ppm_checklist` VALUES (825, 1, 'ppns - Roads, Hard-Shoulders, Footpaths, Road Furniture & Signage ', 'C002A', '1', NULL, 'The following guidelines shall be followed:\n1. Must wear safety vest to aware road user.\n2. Use proper and suitable personal protective equipment.\n3. Barricade the area of road under maintenance.\n4. Refer SDS for emergency guidelines during any renewal road marking works ', 465, 277010, '00:00:00', '00:00:00', NULL, '2020-09-07 10:13:51', '2020-09-07 10:11:15', 1, 1);
INSERT INTO `ppm_checklist` VALUES (826, 1, 'ppns - Pantry Storage Tank/ Suction Water Tank/ Cold Water Storage Tank ', 'C003A', '1', NULL, 'The following guidelines shall be followed:\n1. Use proper and suitable personal protective equipment.\n2. Put the signage ‘DANGER: CONFINED SPACE.DO NOT ENTERS’\n3. Ensure the technicians are aware of the hazards/ aspect and well-trained job.\n4. Used buddy syste', 466, NULL, NULL, NULL, NULL, '2020-09-07 10:20:12', '2020-09-07 10:17:22', 1, 1);
INSERT INTO `ppm_checklist` VALUES (827, 1, 'ppns - Roofing (Polycarbonate/ Glass Awning/ Metal) ', 'C005A', '1', NULL, 'The following guidelines shall be followed: \n1. Display safety signage at specific defects area. \n2. Use 3 steps ladder while inspect/maintaining the high level.\n3. Use proper and suitable personal protective equipment and harness if needed.\n4. Ensure the technician are aware of the hazards/ aspect and well-trained job. \n\n', 439, NULL, NULL, NULL, NULL, '2020-09-07 10:34:48', '2020-09-07 10:30:40', 1, 1);
INSERT INTO `ppm_checklist` VALUES (828, 1, 'ppns - Ceiling (Plaster Ceiling/ Ceiling Board/ Metal or Aluminium Ceiling) ', 'C005B', '1', NULL, 'The following guidelines shall be followed: \n1. Display safety signage at specific defects area. \n2. Use 3 steps ladder while inspect/maintaining the high ceiling.\n3. Use proper and suitable personal protective equipment and harness if needed.\n4. Ensure the technician are aware of the hazards/ aspect and well-trained job.\n5. Refer SDS for emergency guidelines during any maintaining finishes works.\n6. Make sure working area were in maximum cleanliness after services works. \n\n', 467, NULL, NULL, NULL, NULL, '2020-09-07 10:43:48', '2020-09-07 10:36:02', 1, 1);
INSERT INTO `ppm_checklist` VALUES (829, 1, 'ppns -  Floor and Carpet ', 'C005D', '1', NULL, 'The following guidelines shall be followed:\n1. Display safety signage at specific defects area. \n2. Use proper and suitable personal protective equipment.\n3. Ensure the technician are aware of the hazards/ aspect and well-trained job.\n4. Refer SDS for emergency guidelines during any maintaining finishes works.\n5. Make sure working area were in maximum cleanlin', 468, NULL, NULL, NULL, NULL, '2020-09-07 10:58:01', '2020-09-07 10:51:41', 1, 1);
INSERT INTO `ppm_checklist` VALUES (830, 1, 'ppns -Common Areas Built in Furniture ', 'C005I', '1', NULL, 'The following guidelines shall be followed:\n1. Display safety signage at specific defects area. \n2. Use proper and suitable personal protective equipment.\n3. Ensure the technician are aware of the hazards/ aspect and well-trained job.\n4. Refer SDS for emergency guidelines during any maintaining finishes works.\n5. Make sure working area were in maximum cleanliness after services works. \n ', 251, NULL, NULL, NULL, NULL, '2020-09-07 11:04:12', '2020-09-07 11:03:12', 1, 1);
INSERT INTO `ppm_checklist` VALUES (831, 1, 'ppns - signage', 'C005M', '1', NULL, 'The following guidelines shall be followed:\n1. Display safety signage at specific defects area. \n2. Use proper and suitable personal protective equipment.\n', 252, NULL, NULL, NULL, NULL, '2020-09-07 11:23:38', '2020-09-07 11:22:45', 1, 1);
INSERT INTO `ppm_checklist` VALUES (832, 1, 'ppns - Slopes and Earth Retaining Wall ', 'C006A', '1', NULL, 'The following guidelines shall be followed:\n1. Barricade the defects area by using red-white tape. \n2. Display safety signage at specific defects area. \n3. Use proper and suitable personal protective equipment. ', 469, NULL, NULL, NULL, NULL, '2020-09-07 11:28:52', '2020-09-07 11:25:45', 1, 1);
INSERT INTO `ppm_checklist` VALUES (833, 1, 'ppns - Pantry Storage Tank/ Suction Water Tank/ Cold Water Storage Tank (Sub-Contractor Monitoring) ', 'C007A', '1', NULL, 'The following guidelines shall be followed:\n1. Ensure there is competent person (sub-contractor representative monitoring) for confined space.\n2. Ensure that tanks are safe to be entered by workers.\n3. Use proper and suitable personal protective equipment.\n4. Put the signage ‘DANGER: CONFINED SPACE.DO NOT ENTERS’\n5. Ensure to blow the air out before maintaining work start. \n6. Used buddy system. \n ', 470, NULL, NULL, NULL, NULL, '2020-09-07 11:37:34', '2020-09-07 11:34:00', 1, 1);
INSERT INTO `ppm_checklist` VALUES (834, 1, 'perkeso - acsu', 'M003A', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.\n5. Reset selector switch to BMS and start using BMS at control room\n6. Wear complete PPE\n7. Ensure no interruption for resident user during works carry out\n8. Provide protection for any equipment before service to avoid from damaged or dirty\n', 43, 99829, '00:15:00', '00:45:00', 1, '2020-09-07 15:53:20', '2020-09-07 15:46:00', 1, 1);
