INSERT INTO `ppm_checklist` VALUES (917, 1, 'ppns - Sub Switch Board (Y)', 'E003R', '1', NULL, 'The following guidelines shall be followed:\n1.   Make sure proper Personal Protective Equipment is intact.\n2.   Do not wear loose clothing or jewellery while working around equipment.\n3.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n4.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.', 302, 235706, '00:30:00', '01:00:00', 1, '2020-12-15 15:49:19', '2020-12-15 15:41:30', 1, 1);
INSERT INTO `ppm_checklist` VALUES (918, 1, 'perkeso - water heater solar panel (M)', 'E007A', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, servicing or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.\n\n', 481, 235911, '00:45:00', '01:00:00', 1, '2020-12-17 11:49:06', '2020-12-17 11:03:22', 1, 1);
INSERT INTO `ppm_checklist` VALUES (919, 1, 'perkeso - Roller Shutter ', 'M006A ', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.', 85, 100164, '00:15:00', '00:30:00', 1, '2020-12-17 11:26:56', '2020-12-17 11:12:58', 1, 1);
INSERT INTO `ppm_checklist` VALUES (920, 1, 'perkeso - buggy (D)', 'M010A', '1', NULL, '-', 367, NULL, NULL, NULL, NULL, '2020-12-17 14:16:01', '2020-12-17 12:17:57', 1, 1);
INSERT INTO `ppm_checklist` VALUES (921, 1, 'perkeso - buggy (M)', 'M010C', '1', NULL, '-', 367, 99716, NULL, NULL, NULL, '2020-12-17 14:54:17', '2020-12-17 14:16:12', 1, 1);
INSERT INTO `ppm_checklist` VALUES (922, 1, 'perkeso - Ambulance (M)', 'M011C', '1', NULL, '-', 366, 99841, NULL, NULL, NULL, '2020-12-17 16:25:39', '2020-12-17 15:16:44', 1, 1);
INSERT INTO `ppm_checklist` VALUES (923, 1, 'perkeso - precision air condition unit', 'E003B', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.\n5. Reset selector switch to BMS and start using BMS at control room\n6. Wear complete PPE\n7. Ensure no interruption for resident user during works carry out\n8. Provide protection for any equipment before service to avoid from damaged or dirty', 220, 224720, '00:15:00', '00:45:00', NULL, '2020-12-17 16:58:15', '2020-12-17 16:45:31', 1, 1);
INSERT INTO `ppm_checklist` VALUES (924, 1, 'perkeso - Water Cooled Package Unit (M,Y)', 'M001B', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.\n', 238, 224727, '00:15:00', '00:45:00', 1, '2020-12-17 21:44:55', '2020-12-17 21:08:05', 1, 1);
INSERT INTO `ppm_checklist` VALUES (925, 1, 'perkeso - buggy (W)', 'M010B', '1', NULL, '-', 367, NULL, NULL, NULL, NULL, '2020-12-17 22:55:14', '2020-12-17 22:51:26', 1, 1);
INSERT INTO `ppm_checklist` VALUES (927, 1, 'perkeso - Ambulance (D)', 'M011A', '1', NULL, '-', 366, 99947, NULL, NULL, NULL, '2020-12-18 08:23:41', '2020-12-18 08:19:40', 1, 1);
INSERT INTO `ppm_checklist` VALUES (928, 1, 'perkeso - Ambulance (W)', 'M011B', '1', NULL, '-', 366, 100120, NULL, NULL, NULL, '2020-12-18 10:41:26', '2020-12-18 10:28:04', 1, 1);
INSERT INTO `ppm_checklist` VALUES (929, 1, 'perkeso - HT Panel 11kV(VCB) (D)', 'E001A', '1', NULL, '\nThe following guidelines shall be followed:\n1.	Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n2.	Ensure using Personal Protective Equipment (PPE) & proper tools during inspection or maintenance activity.\n3.	Isolate power supply before doing maintenance activity.\n4.	Make sure doors or other devices leading to High Voltage zones shall be kept locked after in use.\n5.	Ensure no any obstacle occurred at the location.', 20, 225397, '00:05:00', '00:15:00', 0, '2020-12-18 12:00:29', '2020-12-18 11:43:30', 1, 1);
INSERT INTO `ppm_checklist` VALUES (930, 1, 'perkeso - ht panel 11kv(vcb)(D)', 'E001B', '1', NULL, 'The following guidelines shall be followed:\n1.	Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n2.	Ensure using Personal Protective Equipment (PPE) & proper tools during inspection or maintenance activity.\n3.	Isolate power supply before doing maintenance activity.\n4.	Make sure doors or other devices leading to High Voltage zones shall be kept locked after in use.\n5.	Ensure no any obstacle occurred at the location.', 20, NULL, NULL, NULL, NULL, NULL, '2020-12-18 12:09:26', NULL, 5);
