INSERT INTO `ppm_checklist` VALUES (968, 1, 'ppns - earthing&lightning - BODY FRAME EARTHING - BLOCK C (M)', 'E005A', '1', NULL, 'The following guidelines shall be followed:\n1.   Make sure proper Personal Protective Equipment is intact.\n2.   Do not wear loose clothing or jewellery while working around equipment.\n3.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n4.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.\n', 30, 235283, '02:00:00', '04:00:00', 1, '2020-12-31 23:17:18', '2020-12-31 23:14:56', 1, 1);
INSERT INTO `ppm_checklist` VALUES (969, 1, 'PPNS - MAIN SWICH BOARD (H)', 'E003E', '1', NULL, 'E003E\n\nSafety Precaution/ General Guidelines prior to maintenance activity\nThe following guidelines shall be followed:\n1.   Make sure proper Personal Protective Equipment is intact.\n2.   Do not wear loose clothing or jewellery while working around equipment.\n3.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n4.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.\n', 300, 228476, '00:30:00', '01:15:00', 1, '2021-01-01 00:50:37', '2021-01-01 00:49:04', 1, 1);
INSERT INTO `ppm_checklist` VALUES (970, 1, 'matrade - escalator', 'M004B', '1', NULL, 'The following guidelines shall be followed:\n1.   To switch off/lock main isolator or MCCB.\n2.   To check no power supply at control panels.\n3.   To use proper signage on electrical panels.\n4.   To use proper safety attire when working in high levels. ', 84, NULL, NULL, NULL, NULL, '2021-01-04 16:56:01', '2021-01-04 16:31:06', 1, 1);
INSERT INTO `ppm_checklist` VALUES (971, 1, 'matrade - lift', 'M004A', '1', NULL, 'The following guidelines shall be followed:\n1.   To switch off/lock main isolator or MCCB\n2.   To check no power supply at control panels\n3.   To use proper signage on electrical panels\n4.   To use proper safety attire when working on high levels', 296, NULL, NULL, NULL, NULL, '2021-01-04 17:18:14', '2021-01-04 16:57:33', 1, 1);
INSERT INTO `ppm_checklist` VALUES (972, 1, 'matrade - automatic co2', 'M003B', '1', NULL, 'The following guidelines shall be followed:\n1. Isolate all Buzzer, Bell and Gas Discharge isolation switches\n2. Display safety signages at specific control panel.\n3. Fire curtain, solenoid actuator and plunger must be fix to normal position after testing completed.\n', 72, 106142, NULL, NULL, NULL, '2021-01-05 09:59:43', '2021-01-05 09:46:43', 1, 1);
INSERT INTO `ppm_checklist` VALUES (973, 1, 'matrade - fire alarm system', 'M003A', '1', NULL, 'The following guidelines shall be followed :\n     1. Disable Master Zone before carrying out maintenance activities\n     2. Test smoke detector either by using artificial smoke spray or test magnet\n     3. Upon completion of the activities, make sure that all systems are set to normal mode\n', 66, 225372, '00:30:00', '01:00:00', NULL, '2021-01-05 10:52:23', '2021-01-05 10:07:49', 1, 1);
INSERT INTO `ppm_checklist` VALUES (974, 1, 'matrade - fireman intercome', 'M003C', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at specific control panel.\n\n', 76, NULL, NULL, NULL, NULL, '2021-01-05 11:15:35', '2021-01-05 10:58:02', 1, 1);
