INSERT INTO `ppm_checklist` VALUES (1125, 1, 'educity - vrv', 'M001D', '1', 'checklist vrv for educity', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel or in the unit.\n4. Display safety signages at specific control panel.\n5. Wear complete PPE.\n6. Ensure no interruption for resident user during works carry out.\n7. Provide protection for any equipment before service to avoid from damaged or dirty.', 53, 224485, '00:15:00', '00:45:00', 1, '2021-04-22 14:42:33', '2021-04-22 14:30:43', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1126, 1, 'bnmsk - feeder pillar_new', 'E002D_new', '1', NULL, 'The following guidelines shall be followed:\n1.	Switch off the Board if maintenance activity requires adjustments, lubrications, repairs or etc.\n2.	  Two technicians must be present to achieve safety operations and carry out PPM.\n3.	 Display safety signages at specific Board during carry out PPM.', 26, 152834, '00:15:00', '00:30:00', 1, '2021-05-28 16:03:33', '2021-05-28 15:49:49', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1127, 1, 'ppns - make up pump-new', 'M002J', '1', NULL, 'The following guidelines shall be followed:\n    1. Inform Mechanical Competent Personnel. \n1. Do not enter the tank for 15 min after open the tank manhole access\n2. Bring along the torch light for checking the inner tank area \n3. This exercise must be carried at least with 2 manpower and knowing by the supervisor\n4. Wear basic PPE when do the inspection\n5. Follow the safety requirement such as safety temporary signage, flag-man, safety vest and etc.', 277, 225368, '00:30:00', '01:00:00', NULL, '2021-07-02 18:03:23', '2021-07-02 17:57:00', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1128, 1, 'bnmsk - heat exchanger', 'M007A', '1', NULL, 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrication or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signages at the specific control panel.\n5. Reset selector switch to BCS and start by BCS.', 55, 180227, '00:45:00', '01:15:00', NULL, '2021-07-12 16:50:06', '2021-07-12 16:46:21', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1129, 1, 'bnmsk - gondola', 'M', '1', NULL, ' ', 88, 224996, '00:30:00', '01:30:00', NULL, '2021-07-12 18:44:47', '2021-07-12 18:43:53', 1, 1);
