INSERT INTO `ppm_checklist` VALUES (1306, 1, 'bnmhq  - lv panel(ssb/db)', 'E002C', '1', 'checklist - lv panel(ssb/db) for bnmhq', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repairs. \n2. Isolate incoming power supply if required.  \n3. Display safety signages at specific control panel.\nOR,\nRefer to ……………………………………..', 25, 290795, '00:15:00', '00:30:00', 0, '2022-07-20 10:41:33', '2022-07-20 10:10:17', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1307, 1, 'bnmhq - lv panel msb(acb) B1C', 'E002A(ii)', '1', 'checklist - lv_panel_msb(acb) B1C for bnmhq', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.\nOR,\nRefer to …………………….', 23, 290837, '00:15:00', '00:45:00', 1, '2022-07-20 12:00:41', '2022-07-20 11:06:34', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1308, 1, 'bnmhq - lv panel msb(acb) LB2B', 'E002A(i)', '1', 'checklist - lv_panel_msb(acb) LB2B for bnmhq', 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.\nOR,\nRefer to …………………….', 23, 290882, '00:15:00', '00:45:00', 1, '2022-07-20 14:43:37', '2022-07-20 12:17:01', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1309, 1, 'bnmhq - lv panel msb(acb) 1D', 'E002A', '1', NULL, 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.\nOR,\nRefer to …………………….', 23, 290961, '00:15:00', '00:45:00', 1, '2022-07-20 15:19:12', '2022-07-20 15:04:48', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1314, 1, 'uitmmukah - Fire Alarm Panel', 'M006A', '1.1', 'Fire Protection Services - Fire Alarm System', 'The following guidelines shall be followed :\n     1. Disable Master Zone before carrying out maintenance activities\n     2. Test smoke detector either by using artificial smoke spray or test magnet\n     3. Upon completion of the activities, make sure that all systems are set to normal mode\n', 66, 313584, '00:15:00', '00:30:00', 0, '2022-09-29 15:17:51', '2022-09-29 10:28:03', 926, 1);
INSERT INTO `ppm_checklist` VALUES (1315, 1, 'uitmmukah - Mechanical Fan System', 'M005A', '1', 'Mechanical Fan System', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signage at specific control panel.\n5. Reset selector switch to BCS and start by BCS', 45, 322255, '00:15:00', '00:30:00', 0, '2022-09-29 16:52:03', '2022-09-29 15:36:31', 926, 1);
INSERT INTO `ppm_checklist` VALUES (1317, 1, 'IN - HT Switchboard & Gas Circuit Breaker (Y)', 'E001A', '1', NULL, 'The following guidelines shall be followed:\n1.Obtain permit to work (PTW), Use appropriate PPE, equipment/tools and safety temporary signage\n2.Refer HIRARC/ Aspect Impact\n3.In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operations. Inform Incident Response Personnel (IRP)\n4.Report any hazard situation to supervisor immediately \n5.Do not wear loose clothing or jewellery while working around equipment\n6.Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n7.Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use', 1523, 317559, '00:00:00', '00:00:00', 2, '2022-11-07 12:06:06', '2022-10-11 11:33:16', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1318, 1, 'IN - Transformer (Y)', 'E001B ', '1', NULL, 'The following guidelines shall be followed:\n1. Obtain permit to work (PTW), Use appropriate PPE, equipment/tools and safety temporary signage\n2. Refer HIRARC/ Aspect Impact\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operations. Inform Incident Response Personnel (IRP)\n4. Report any hazard situation to supervisor immediately\n5. Do not wear loose clothing or jewellery while working around equipment.\n6. Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n7. Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.', 1524, 317818, '00:00:00', '00:00:00', 2, '2022-11-07 12:07:00', '2022-10-12 09:35:09', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1319, 1, 'IN - MAIN SWITCH BOARD (MSB)/ SUB SWITCH BOARD (SSB) (Q)', 'E002A', '1', NULL, 'The following guidelines shall be followed:\n1.Refer HIRARC/ Aspect Impact\n2.In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform Incident Response Personnel (IRP)\n3.Report any hazard situation to HOD/ Supervisor immediately \n4.Advance notice on shutdown has been sent to affected department\n5.Do not wear loose clothing or jewellery while working around equipment\n6.Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n7.Make sure all gates, doors or other devices leading to High Voltage Zone shall be kept locked after in use', 1525, 317990, '00:00:00', '00:00:00', 2, '2022-11-29 16:56:52', '2022-10-12 10:28:25', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1320, 1, 'IN - DISTRIBUTION BOARD (DB) (H)', 'E002B', '1', NULL, 'The following guidelines shall be followed:\n1. Obtain permit to work (PTW) if necessary, Use appropriate PPE and equipment/tools\n2. Refer HIRARC/ Aspect Impact (if necessary)\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform SHE Department (if necessary)\n4. Report any hazard situation to HOD/ Supervisor immediately\n5. Follow the safety requirement such as safety temporary signage, safety vest and etc. (if necessary)\n6. Advance notice on shutdown has been sent to effected department\n7. Do not wear loose clothing or jewellery while working around equipment', 301, 335838, '00:00:00', '00:00:00', 2, '2022-11-07 12:14:21', '2022-10-13 15:53:56', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1321, 1, 'IN - FEEDER PILLAR (M)', 'E002C ', '1', NULL, 'The following guidelines shall be followed:\n1. Refer HIRARC/ Aspect Impact\n2. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power\nsource immediately and stop all this operation.\n3. Report any hazard situation to supervisor immediately\n4. Make sure the Personal Protective Equipment is intact\n5. Switch off the panel if maintenance activity requires adjustments, lubrications, repairs or etc\n6. Two technicians must be present to achieve safety operations and carry out PPM\n7. Display safety signage at specific panel during PPM.', 26, 335848, '00:00:00', '00:00:00', 2, '2022-10-13 16:17:58', '2022-10-13 16:01:51', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1322, 1, 'IN - INTERNAL & EXTERNAL LUMINARIES (M)', 'E002D', '1', NULL, 'The following guidelines shall be followed:\n1.Refer HIRARC/Aspect Impact.\n2.In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation.\n3.Report any hazard situation to supervisor immediately.\n4.Inform the relevant Department during each visit and obtain approval.\n5.Ensure all keys for locked rooms are available at the time of inspection', 1526, 335926, '00:00:00', '00:00:00', 2, '2022-10-13 16:17:37', '2022-10-13 16:14:00', 1, 1);
