INSERT INTO `ppm_checklist` VALUES (1457, 1, 'Perkeso - Physiologic Monitoring System, Acute Care (2)', 'M05(2)', '1', NULL, 'If there is evidence of body fluid contamination, submit the device for cleaning & decontamination before inspecting it. Wear appropriate Personal Protection Equipment (PPE) during work. Wear grounded electrostatic wristband when handling PCB or electronic components. Refer to the safety procedure for additional precautions and guidance as per manufacturer guidelines. Make sure the test equipment used are duly calibrated', 484, NULL, '00:00:00', '00:00:00', 2, NULL, '2022-11-23 02:02:11', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1458, 1, 'Electrocardio', 'M05A', '1', NULL, 'If there is evidence of body fluid contamination, submit the device for cleaning & decontamination before inspecting it. Wear appropriate Personal Protection Equipment (PPE) during work. Wear grounded electrostatic wristband when handling PCB or electronic components. Refer to the safety procedure for additional precautions and guidance as per manufacturer guidelines. Make sure the test equipment used are duly calibrated', 498, NULL, NULL, NULL, NULL, NULL, '2022-11-23 09:33:01', 1, 2);
