INSERT INTO `ppm_checklist` VALUES (1465, 1, 'IN - RESTROOM (D)', 'H001C', '1', NULL, 'The following guidelines shall be followed:\n1. Use appropriate PPE and equipment/tools\n2. Refer HIRARC/ Aspect Impact (if necessary)\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform Incident Response Personnel (IRP)\n4. Report any hazard situation to HOD/ Supervisor immediately', 1572, NULL, '00:00:00', '00:00:00', 2, '2023-01-15 17:02:22', '2022-11-24 12:10:30', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1466, 1, 'IN - HT Switchboard & Gas Circuit Breaker (M)', 'E001A', '1', NULL, 'The following guidelines shall be followed:\n1.Obtain permit to work (PTW), Use appropriate PPE, equipment/tools and safety temporary signage\n2.Refer HIRARC/ Aspect Impact\n3.In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operations. Inform Incident Response Personnel (IRP)\n4.Report any hazard situation to supervisor immediately \n5.Do not wear loose clothing or jewellery while working around equipment\n6.Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n7.Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use', 1523, 333623, '00:00:00', '00:00:00', 2, NULL, '2022-11-29 16:12:03', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1467, 1, 'IN - Transformer (M)', 'E001B', '1', NULL, 'The following guidelines shall be followed:\n1. Obtain permit to work (PTW), Use appropriate PPE, equipment/tools and safety temporary signage\n2. Refer HIRARC/ Aspect Impact\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operations. Inform Incident Response Personnel (IRP)\n4. Report any hazard situation to supervisor immediately\n5. Do not wear loose clothing or jewellery while working around equipment.\n6. Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n7. Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.', 1524, 333634, '00:00:00', '00:00:00', 2, NULL, '2022-11-29 16:20:59', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1468, 1, 'IN - Transformer (B)', 'E001B', '1', NULL, 'The following guidelines shall be followed:\n1. Obtain permit to work (PTW), Use appropriate PPE, equipment/tools and safety temporary signage\n2. Refer HIRARC/ Aspect Impact\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operations. Inform Incident Response Personnel (IRP)\n4. Report any hazard situation to supervisor immediately\n5. Do not wear loose clothing or jewellery while working around equipment.\n6. Members of a working party may be admitted to a High Voltage Zone by an Authorised Person.\n7. Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.', 1524, 333640, '00:00:00', '00:00:00', 2, NULL, '2022-11-29 16:21:36', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1469, 1, 'IN - MAIN SWITCH BOARD (MSB)/ SUB SWITCH BOARD (SSB) (M)', 'E002A', '1', NULL, 'The following guidelines shall be followed:\n1.Refer HIRARC/ Aspect Impact\n2.In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform Incident Response Personnel (IRP)\n3.Report any hazard situation to HOD/ Supervisor immediately \n4.Advance notice on shutdown has been sent to affected department\n5.Do not wear loose clothing or jewellery while working around equipment\n6.Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n7.Make sure all gates, doors or other devices leading to High Voltage Zone shall be kept locked after in use', 1525, 333727, '00:00:00', '00:00:00', 2, NULL, '2022-11-29 16:56:15', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1470, 1, 'IN - MAIN SWITCH BOARD (MSB)/ SUB SWITCH BOARD (SSB) (Y)', 'E002A', '1', NULL, 'The following guidelines shall be followed:\n1.Refer HIRARC/ Aspect Impact\n2.In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform Incident Response Personnel (IRP)\n3.Report any hazard situation to HOD/ Supervisor immediately \n4.Advance notice on shutdown has been sent to affected department\n5.Do not wear loose clothing or jewellery while working around equipment\n6.Members of a working party may be admitted to a High Voltage Zone by an Authorised Person\n7.Make sure all gates, doors or other devices leading to High Voltage Zone shall be kept locked after in use', 1525, 335770, '00:00:00', '00:00:00', 2, NULL, '2022-11-29 16:56:28', 1, 1);
