INSERT INTO `ppm_checklist` VALUES (1501, 1, 'uitmmukah - Fire Extinguisher', 'M006B', '1', 'Checklist for Fire Extinguisher at UiTM Mukah', 'The following guidelines shall be followed:\n1. Ensure extinguishers and cylinders are in their correct location\n2. Isolate all isolation switches at panel and disconnect wiring\n3. To weigh the cylinder, disconnect the system piping from the discharge actuator valve. Remove the cylinder with their actuator\nvalves intact and weigh them.\n4. Set value is the total weight for each extinguisher/cylinder including the gas/dry powder and intact accessories.', 305, NULL, '00:15:00', '00:30:00', 0, '2022-12-14 16:33:43', '2022-12-14 16:23:30', 926, 1);
INSERT INTO `ppm_checklist` VALUES (1502, 1, 'IN - WATER COOLED CHILLER (M)', 'M001A', '1', NULL, 'The following guidelines shall be followed:\n1. Obtain permit to work (PTW) if necessary, Use appropriate PPE, equipment/tools and safety temporary signage\n2. Refer HIRARC/ Aspect Impact\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform Incident Response Personnel (IRP)\n4. Report any hazard situation to HOD/ Supervisor immediately\n5. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n6. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n7. Check and double confirm there is no electricity in the starter panel or in the unit.\n8. Display safety signage at specific control panel.\n9. Reset selector switch to BMS and make sure chillers is running in ‘Auto Mode’ (After completion tasks).', 1447, 352654, '00:00:00', '00:00:00', 2, NULL, '2023-01-10 16:36:09', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1503, 1, 'IN - GENERATOR SET (M)', 'E002Q', '1', NULL, 'The following guidelines shall be followed:\n1. Obtain permit to work (PTW) & Use appropriate PPE\n2. Please refer HIRARC/ Aspect Impact\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operation.\n4. Report any hazard situation to supervisor immediately\n5. Ensure availability of circuit diagram, safety chart, first aid kit, danger sign, fire extinguisher and rubber mat.\n6. Put the automatic start-stop switch to STOP position before working on the equipment to prevent accidental starting.', 1587, NULL, '00:00:00', '00:00:00', 2, NULL, '2023-01-10 16:59:14', NULL, 5);
INSERT INTO `ppm_checklist` VALUES (1504, 1, 'IN - STREET LIGHTINGS & FENICING LIGHTINGS (Q)', 'E002R', '1', NULL, 'The following guidelines shall be followed:\n1. Please refer HIRARC/ Aspect Impact\n2. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operation.\n3. Report any hazard situation to supervisor immediately\n4. Switch off the panel if maintenance activity requires adjustments, lubrications, repairs or etc\n5. Two technicians must be present to achieve safety operations and carry out PPM\n6. Display safety signage at specific panel during PPM.', 1588, 357266, '00:00:00', '00:00:00', 2, '2023-01-10 17:26:54', '2023-01-10 17:15:28', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1505, 1, 'IN - STREET LIGHTINGS & FENICING LIGHTINGS (H)', 'E002R', '1', NULL, 'The following guidelines shall be followed:\n1. Please refer HIRARC/ Aspect Impact\n2. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all these operation.\n3. Report any hazard situation to supervisor immediately\n4. Switch off the panel if maintenance activity requires adjustments, lubrications, repairs or etc\n5. Two technicians must be present to achieve safety operations and carry out PPM\n6. Display safety signage at specific panel during PPM.', 1588, 346237, '00:00:00', '00:00:00', 2, NULL, '2023-01-10 17:27:19', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1506, 1, 'uitmmukah - Smoke Spill Fan', 'M005B', '1.1', 'Checklist for smoke spill fan at UiTM Mukah', 'The following guidelines shall be followed:\n1. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n2. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n3. Check and double confirm there is no electricity in the starter panel nor in the unit.\n4. Display safety signage at specific control panel.\n5. Reset selector switch to BCS and start by BCS', 327, 346381, '00:15:00', '00:30:00', 1, '2023-01-11 13:53:55', '2023-01-11 07:26:14', 926, 1);
