INSERT INTO `ppm_checklist` VALUES (1557, 1, 'uitmmukah - Fire Alarm Panel (Daily)', 'M006A (D)', '1', 'Daily checklist for fire alarm panel', 'The following guidelines shall be followed :\n1. Disable Master Zone before carrying out maintenance activities\n2. Test smoke detector either by using artificial smoke spray or test magnet\n3. Upon completion of the activities, make sure that all systems are set to normal mode', 66, 352196, '00:03:00', '00:30:00', 0, '2023-02-11 07:47:20', '2023-02-03 15:30:04', 926, 1);
