INSERT INTO `ppm_checklist` VALUES (1568, 1, 'IN - DENTAL SURGERY EQUIPMENT (Q)', 'M013C', '1', NULL, 'The following guidelines shall be followed:\n1. Use appropriate PPE, equipment/tools and safety temporary signage\n2. Refer HIRARC/ Aspect Impact\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform Incident Response Personnel (IRP)\n4. Report any hazard situation to supervisor immediately\n5. Switch off the unit if maintenance activity requires adjustments, lubrications or repair.\n6. Isolate power supply by turning off the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n7. Check and double confirm there is no electricity in the starter panel or in the unit.', 1621, 352394, '00:00:00', '00:00:00', 2, '2023-02-05 19:00:20', '2023-02-05 18:13:08', 1, 1);
INSERT INTO `ppm_checklist` VALUES (1569, 1, 'IN - FALCON (Q)', 'M009A', '1', NULL, 'The following guidelines shall be followed:\n1. Obtain permit to work (PTW) if necessary, Use appropriate PPE, equipment/tools and safety temporary signage\n2. Refer HIRARC/ Aspect Impact\n3. In case of emergency during the execution of the work, or equipment failure, TURN OFF the power source immediately and stop all this operation. Inform Incident Response Personnel (IRP)\n4. Report any hazard situation to supervisor immediately\n5. Switch off the unit if maintenance activity requires adjustment, lubrications or repair.\n6. Isolate power supply by turning of the primary & secondary (if available) incoming electricity supply MCCB or isolator.\n7. Check and double confirm there is no electricity whether in the starter panel nor in the unit.\n\nAll above works STRICTLY MUST BE PERFORM BY THE SPECIALIST VENDOR or ORIGINAL SUPPLIER to ensure safety and performance assurance of machinery.', 1498, NULL, '00:00:00', '00:00:00', 2, '2023-02-05 19:11:05', '2023-02-05 19:06:20', 1, 1);
