INSERT INTO `ppm_checklist` VALUES (1680, 1, 'tapah - roads, hard-shoulders & footpaths (M)', 'C001A', '1', NULL, 'The following guidelines shall be followed:\n1.   Wear proper PPE.\n2.   Walk at shoulder of road while inspection.\n3.   Prepare some cone for working on road.\n4.   Follow the safety requirement such as safety temporary signage, safety vest and etc\nOR,\nRefer to ………………………………………\n', 1, NULL, '00:00:00', '00:00:00', 1, '2023-03-13 14:06:05', '2023-03-13 14:02:50', 525, 1);
INSERT INTO `ppm_checklist` VALUES (1681, 1, 'tapah - Main Fire Alarm Panel (M)', 'M003A', '1', NULL, 'The following guidelines shall be followed :\n     1. Disable Master Zone before carrying out maintenance activities\n     2. Test smoke detector either by using artificial smoke spray or test magnet\n     3. Upon completion of the activities, make sure that all systems are set to normal mode\n', 66, NULL, '00:00:00', '00:00:00', 1, '2023-03-13 14:36:49', '2023-03-13 14:05:58', 1328, 1);
