INSERT INTO `ppm_checklist` VALUES (1706, 1, 'tapah - lv panel –ssb/db/feeder pillar', 'E001C', '1', NULL, 'The following guidelines shall be followed:\n1. Make sure the Personal Protective Equipment is intact.   \n2. Switch off the panel if maintenance activity requires adjustments, lubrications, repairs or etc.\n3. Two technicians must be present to achieve safety operations and carry out PPM.\n4. Display safety signage at specific panel during PPM.\n', 25, NULL, '00:00:00', '00:00:00', 1, '2023-03-13 15:48:21', '2023-03-13 15:35:37', 1330, 1);
