INSERT INTO `ppm_checklist` VALUES (1712, 1, 'tapah - ht panel 11KV (vcb)(m)', 'E001D', '1', NULL, 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewelry while working around equipment\n2.   Members of a working party may be admitted to a High Voltage Zone by an Authorized Person\n3.   Make sure all gates, doors or other devices leading to High Voltage zones shall be kept locked after in use.\n', 20, NULL, '00:00:00', '00:00:00', 1, '2023-03-13 16:26:49', '2023-03-13 15:52:23', 1330, 1);
INSERT INTO `ppm_checklist` VALUES (1713, 1, 'tapah - Painting Touch - up (M)', 'C004J', '1', NULL, 'The following guidelines shall be followed:\n1.   Collective protection systems such as scaffolds for high work.\n2.   Also wearing safety wire harness.\n3.   Wear basic PPE when do the inspection\n\nOR,\nRefer to ………………………………………\n', 18, NULL, '00:00:00', '00:00:00', 1, '2023-03-13 15:54:49', '2023-03-13 15:53:16', 525, 1);
