INSERT INTO `ppm_checklist` VALUES (1717, 1, 'tapah - ABC Dry Powder-9kg and CO2-2.2kg (M)', 'M003B', '1', NULL, 'The following guidelines shall be followed:\n1.	Ensure extinguishers and cylinders are in their correct location\n2.	Isolate all isolation switches at panel and disconnect wiring\n3.	To weigh the cylinder, disconnect the system piping from the discharge actuator valve. Remove the cylinder with their actuator valves intact and weigh them.\n4.	Set value is the total weight for each extinguisher/cylinder including the gas/dry powder and intact accessories.\n', 1630, NULL, '00:00:00', '00:00:00', 1, '2023-03-14 10:24:33', '2023-03-13 16:14:10', 1328, 1);
INSERT INTO `ppm_checklist` VALUES (1718, 1, 'tapah - cabling (Q)', 'I001A', '1', NULL, 'The following guidelines shall be followed:\n1. Use proper clean wash cloth preferred ESD protected cloth\n2. Use Wrist wrap (ESD) if you want to touch equipment (if necessary)    \n3. Wear proper PPE during working.\nOR,\nRefer to ………………………………………\n', 153, NULL, '00:00:00', '00:00:00', 1, '2023-03-13 16:24:14', '2023-03-13 16:15:32', 525, 1);
