INSERT INTO `ppm_checklist` VALUES (1720, 1, 'tapah - ht panel 11kv (vcb) (shutdown) (Y)', 'E001E', '1', NULL, 'The following guidelines shall be followed:\n1.   Do not wear loose clothing or jewellery while working around equipment\n2.   Inform / notice to related department/authority a week before shutdown works\n3.   Make sure the incoming supply Vacuum Circuit Breaker is totally disconnected and draw out if required\n4.   Apply Log out/Tag out safety procedure\n5.   Use proper Signboards and personal protective equipment and make sure there are two technicians are present\n', 21, NULL, '00:00:00', '00:00:00', 1, '2023-03-14 11:40:52', '2023-03-13 16:38:23', 1330, 1);
