INSERT INTO `ppm_checklist_qual` VALUES (18175, 'Miscellaneous - Carpet Finishes Cleaning - Shampoo carpet at corridors and any other carpeted areas using a steam shampoo. Care will be taken to remove all excess moisture from carpet fibres.(H)', '2(e)', 6, 1530, 1);
